const params = {};
if ($.input.sortOrder) params.sort_order = $.input.sortOrder;
if ($.input.externalId) params.external_id = $.input.externalId;
return { params };

const resp = $.steps.searchTickets.response || {};
const tickets = (resp.tickets || []).map(t => ({
  id: t.id || '',
  subject: t.subject || '',
  status: t.status || '',
  priority: t.priority || '',
  type: t.type || '',
  createdAt: t.created_at || '',
  updatedAt: t.updated_at || '',
  tags: t.tags || [],
  assigneeId: t.assignee_id || null
}));

const meta = resp.meta || {};
return {
  tickets,
  totalTickets: tickets.length,
  hasMore: meta.has_more || false,
  afterCursor: meta.after_cursor || null,
  summary: `Found ${tickets.length} ticket${tickets.length === 1 ? '' : 's'}`
};
